css:
/* FOR THE PINK BANNER SHOWING EXHIBITION NAME AND DATES */
.debrief-dates p {
  color: var(--main-background); /* This allows the smaller (<p>) text within the pink banners to be white text) */
}

/* FOR THE THIN IMAGE BANNERS AT THE TOP OF SOME PAGES */
.image-block-title h1 {
  color: var(--pink); /* Makes the text pink */
  background-color: var(--main-background); /* Makes the block behind the header white */
  padding: 20px 40px;        /* Creates area around the header */
  display: inline-block;     /* Wrapping the header for responsive screens */
}

p.single-item__introduction br {
  margin-bottom: 1rem;
}

.main {
  padding: 0rem 30rem;
}
